const items = $input.all();
const triggerData = $('Execute Workflow Trigger').first().json;

if (items.length > 0 && items[0].json && items[0].json.answer) {
  const kb = items[0].json;
  return [{
    json: {
      status: 'success',
      intent_handled: 'faq_query',
      category: kb.category,
      question_matched: kb.question,
      reply: kb.answer
    }
  }];
} else {
  return [{
    json: {
      status: 'fallback',
      intent_handled: 'faq_query',
      reply: triggerData.ai_output?.direct_response || "Our customer support team is available 24/7. Standard shipping takes 3-5 business days, and we offer a 30-day money-back guarantee on all products. How else may I assist you today?"
    }
  }];
}
